namespace Game.AI.Tactics
{
    /// <summary>
    /// 敵AIが評価する戦術の種類。
    /// </summary>
    public enum MazeEnemyTacticalType
    {
        /// <summary>
        /// 戦術未指定。
        /// </summary>
        None = 0,

        /// <summary>
        /// 対象への直接追跡。
        /// </summary>
        Chase = 1,

        /// <summary>
        /// 対象の進行先への先回り。
        /// </summary>
        Intercept = 2,

        /// <summary>
        /// 脅威からの逃走。
        /// </summary>
        Escape = 3,

        /// <summary>
        /// 縄張りへの帰還。
        /// </summary>
        ReturnToTerritory = 4
    }
}
